package io.github.retbrown.archeryutils.handicaps

import io.github.retbrown.archeryutils.rounds.RoundData
import io.github.retbrown.archeryutils.rounds.Round
import io.github.retbrown.archeryutils.rounds.Rounds
import kotlin.test.Test
import kotlin.test.assertEquals

/**
 * Regression tests for handicaps, comparing against tables generated by the Python library
 * (snapshots in `src/jvmTest/resources/handicaps`). Loops over many rounds for each handicap
 * scheme, so also serves as a regression test for the default rounds.
 */
class HandicapRegressionTest {
    private fun merge(vararg json: String): Map<String, Round> =
        buildMap { for (j in json) putAll(Rounds.fromJson(j)) }

    private val allRounds =
        merge(
            RoundData.AGB_INDOOR, RoundData.WA_INDOOR, RoundData.AA_INDOOR,
            RoundData.AGB_OUTDOOR_IMPERIAL, RoundData.AGB_OUTDOOR_METRIC, RoundData.WA_OUTDOOR,
            RoundData.WA_EXPERIMENTAL, RoundData.AA_OUTDOOR_METRIC, RoundData.WA_FIELD,
            RoundData.AA_FIELD, RoundData.IFAA_FIELD, RoundData.AGB_VI, RoundData.WA_VI,
            RoundData.MISCELLANEOUS,
        )

    private val subsetRounds =
        merge(RoundData.AGB_INDOOR, RoundData.AGB_OUTDOOR_IMPERIAL, RoundData.AGB_OUTDOOR_METRIC, RoundData.WA_OUTDOOR)

    private fun snapshot(name: String): String =
        checkNotNull(javaClass.getResourceAsStream("/handicaps/$name.txt")) { "missing snapshot $name" }
            .readBytes()
            .toString(Charsets.UTF_8)

    private fun compare(expected: String, actual: String) {
        val e = expected.split("\n")
        val a = actual.split("\n")
        assertEquals(e.size, a.size, "row count")
        for (i in e.indices) assertEquals(e[i], a[i], "line $i")
    }

    @Test
    fun handicapSchemesRounds() {
        for (scheme in listOf("AGB", "AGBold", "AA", "AA2")) {
            val table =
                HandicapTable(
                    scheme,
                    DoubleArray(161) { -10.0 + it },
                    allRounds.values.toList(),
                    intPrec = true,
                    roundedScores = true,
                    cleanGaps = true,
                )
            compare(snapshot("rounds_$scheme"), table.format() + "\n")
        }
    }

    @Test
    fun handicapSchemesFloat() {
        for (scheme in listOf("AGB", "AGBold", "AA", "AA2")) {
            val table =
                HandicapTable(
                    scheme,
                    // numpy.arange(0, 10, 0.1) computes start + i * step
                    DoubleArray(100) { it * 0.1 },
                    subsetRounds.values.toList(),
                    intPrec = false,
                    roundedScores = false,
                    cleanGaps = false,
                )
            compare(snapshot("float_$scheme"), table.format() + "\n")
        }
    }
}
